  particles.forEach(function(p){ p.c.opacity(on?0.9:0); });
  if(on){ lastTs=0; rafId=requestAnimationFrame(frame); }
  else if(rafId){ cancelAnimationFrame(rafId); rafId=null; }
}

/* ---------- stage emphasis ---------- */
var STAGES=['Melt with superheated water','Inject compressed air','Lift froth to surface','Full process'];
var stageIdx=0;
function setStage(idx){
  stageIdx=idx;
  var s=STAGES[idx];
  var oW = (s==='Melt with superheated water'||s==='Full process')?1:0.22;
  var oA = (s==='Inject compressed air'||s==='Full process')?1:0.22;
  var oF = (s==='Lift froth to surface'||s==='Full process')?1:0.22;
  gOuter.opacity(oW); gInner.opacity(oA); gMiddle.opacity(oF);
  document.getElementById('pipeStageBtn').textContent='Stage: '+s;
}
function trigger_pipeStage(){ setStage((stageIdx+1)%STAGES.length); }

/* ---------- demo steps ---------- */
var steps=[
  {t:'1. Melt the deposit', n:'Superheated water (~170 °C under pressure) is pumped down the outermost pipe and exits at the bottom manifold into the yellow deposit, melting the solid sulfur into a liquid pool. The outer pipe and its downward arrows are emphasized while the others are dimmed.', stage:0, flow:false},
  {t:'2. Inject compressed air', n:'Compressed air is forced down the innermost pipe to the bottom of the borehole. There it mixes with the molten sulfur, aerating it into a frothy emulsion that is far less dense than the surrounding water. The inner pipe and its downward arrow are emphasized.', stage:1, flow:false},
  {t:'3. Lift the froth', n:'The light sulfur-water-air froth is pushed up through the middle pipe by the pressure of the injected air and emerges at the surface as the "Sulfur, water, and air" stream. The middle pipe and its upward arrows are emphasized.', stage:2, flow:false},
  {t:'4. The whole process at once', n:'Play the continuous animation: all three flows run together — water down the outside melting sulfur, air down the center, froth up the middle — showing a self-sustaining extraction that yields high-purity sulfur on surface cooling.', stage:3, flow:true}
];
var curStep=0;
function applyStep(i){
  curStep=i;
  var st=steps[i];
  document.getElementById('demoNarration').textContent=st.t+' — '+st.n;
  document.getElementById('stepLabel').textContent=(i+1)+' / '+steps.length;
  setStage(st.stage);
  var cb=document.getElementById('processFlowInput');
  cb.checked=st.flow; toggle_processFlow(st.flow);
}
function nextStep(){ applyStep((curStep+1)%steps.length); }
function prevStep(){ applyStep((curStep-1+steps.length)%steps.length); }

/* ---------- hover / click teaching ---------- */
gOuter.css('cursor','pointer').on('mousemove',function(e){showTooltip('Outer pipe: superheated water descends and melts the sulfur deposit.',e);}).on('mouseleave',hideTooltip)
  .on('click',function(){showPopup('Outer pipe — melting','Superheated water is pumped down the outermost annulus and released at the bottom manifold. Its heat liquefies the solid sulfur, forming the molten pool at the base of the borehole.');});
gInner.css('cursor','pointer').on('mousemove',function(e){showTooltip('Inner pipe: compressed air descends to aerate the molten sulfur.',e);}).on('mouseleave',hideTooltip)
  .on('click',function(){showPopup('Inner pipe — aeration','Compressed air travels down the innermost pipe and bubbles into the molten sulfur, creating a light froth that is much less dense than water.');});
gMiddle.css('cursor','pointer').on('mousemove',function(e){showTooltip('Middle pipe: the sulfur-water-air froth is lifted to the surface.',e);}).on('mouseleave',hideTooltip)
  .on('click',function(){showPopup('Middle pipe — recovery','The aerated froth is forced up the middle pipe by air pressure and exits at the surface as a stream of sulfur, water, and air, which is cooled to recover pure sulfur.');});

/* ---------- init ---------- */
setStage(0);
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

