function label(txt,x,y,size,anchor){
  size=size||22; anchor=anchor||'start';
  return gStatic.text(txt).move(x,y).font({size:size, family:'sans-serif', anchor:anchor})
    .fill('#111').attr({'paint-order':'stroke', stroke:'#fff','stroke-width':4,'stroke-linejoin':'round'});
